// Main application class
class PortfolioApp {
    constructor() {
        this.initializeComponents();
        this.setupEventListeners();
    }

    initializeComponents() {
        this.hamburger = document.querySelector('.hamburger');
        this.navLinks = document.querySelector('.nav-links');
        this.heroImage = document.querySelector('.hero-image');
        this.scrollToTopButton = document.getElementById('scrollToTop');
        this.skillsContainer = document.querySelector('.skills-container');
        this.sections = document.querySelectorAll('section');
        this.filterButtons = document.querySelectorAll('.filter-btn');
        this.portfolioItems = document.querySelectorAll('.portfolio-item');
        
        // Initialize scroll animations
        this.scrollAnimations = new ScrollAnimationHandler();
    }

    setupEventListeners() {
        // Hamburger menu
        this.hamburger?.addEventListener('click', () => this.toggleMobileMenu());

        // Hero image loading
        if (this.heroImage) {
            this.heroImage.addEventListener('load', () => this.heroImage.classList.add('loaded'));
            this.heroImage.addEventListener('error', () => this.handleImageError());
        }

        // Navigation
        document.querySelectorAll('.nav-links a').forEach(link => {
            link.addEventListener('click', (e) => this.handleNavClick(e));
        });

        // Scroll events
        window.addEventListener('scroll', this.debounce(() => {
            this.updateActiveNavLink();
            this.toggleScrollToTopButton();
        }, 20));

        // Scroll to top
        this.scrollToTopButton?.addEventListener('click', () => this.scrollToTop());

        // Portfolio filters
        this.filterButtons.forEach(btn => {
            btn.addEventListener('click', () => this.handlePortfolioFilter(btn));
        });

        // Parallax effect

        // Initialize on DOM load
        document.addEventListener('DOMContentLoaded', () => {
            this.updateActiveNavLink();
            this.initializeAOS();
        });
    }

    // Utility Methods
    debounce(func, wait = 20, immediate = true) {
        let timeout;
        return function() {
            const context = this, args = arguments;
            const later = () => {
                timeout = null;
                if (!immediate) func.apply(context, args);
            };
            const callNow = immediate && !timeout;
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
            if (callNow) func.apply(context, args);
        };
    }

    // Event Handlers
    toggleMobileMenu() {
        this.hamburger.classList.toggle('active');
        this.navLinks.classList.toggle('active');
    }

    handleImageError() {
        this.heroImage.src = 'path-to-fallback-image.jpg';
    }

    handleNavClick(e) {
        e.preventDefault();
        const targetId = e.currentTarget.getAttribute('href');
        const targetSection = document.querySelector(targetId);

        if (targetSection) {
            targetSection.scrollIntoView({ behavior: 'smooth' });
            this.hamburger.classList.remove('active');
            this.navLinks.classList.remove('active');
        }
    }

    updateActiveNavLink() {
        const currentPos = window.scrollY;

        this.sections.forEach(section => {
            const sectionTop = section.offsetTop - 100;
            const sectionHeight = section.offsetHeight;
            const sectionId = section.getAttribute('id');

            if (currentPos >= sectionTop && currentPos < sectionTop + sectionHeight) {
                document.querySelectorAll('.nav-links a').forEach(link => {
                    link.classList.remove('active');
                });

                const correspondingLink = document.querySelector(`.nav-links a[href="#${sectionId}"]`);
                if (correspondingLink) {
                    correspondingLink.classList.add('active');
                }
            }
        });
    }

    toggleScrollToTopButton() {
        if (window.pageYOffset > 300) {
            this.scrollToTopButton.classList.add('visible');
        } else {
            this.scrollToTopButton.classList.remove('visible');
        }
    }

    scrollToTop() {
        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }

    handlePortfolioFilter(btn) {
        this.filterButtons.forEach(button => button.classList.remove('active'));
        btn.classList.add('active');

        const filterValue = btn.getAttribute('data-filter');

        this.portfolioItems.forEach(item => {
            item.style.display = 
                (filterValue === 'all' || item.getAttribute('data-category') === filterValue) 
                    ? 'block' 
                    : 'none';
        });
    }

    initializeAOS() {
        AOS.init({
            duration: 1000,
            once: true,
            offset: 100,
            disable: window.innerWidth < 768 // Disable on mobile
        });
    }
}

// Scroll Animation Handler Class
class ScrollAnimationHandler {
    constructor() {
        this.elements = document.querySelectorAll('.animate-on-scroll');
        this.init();
    }

    init() {
        this.setupIntersectionObserver();
        this.setupStaggerAnimations();
    }

    setupIntersectionObserver() {
        const options = {
            root: null,
            rootMargin: '0px',
            threshold: 0.1
        };

        const observer = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                    observer.unobserve(entry.target);
                }
            });
        }, options);

        this.elements.forEach(element => observer.observe(element));
    }

    setupStaggerAnimations() {
        const staggerContainers = document.querySelectorAll('.stagger-animation');
        
        const staggerObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                }
            });
        }, { threshold: 0.1 });

        staggerContainers.forEach(container => staggerObserver.observe(container));
    }
}

// Initialize the application
document.addEventListener('DOMContentLoaded', () => {
    new PortfolioApp();
});